85			cmdSubmit(args[1:])
86		case "health":
87			cmdHealth(args[1:])
88		case "history":
89			cmdHistory(args[1:])
90		case "help", "-h", "--help":
91			heartbeatUsage()
92		default:
93			fmt.Fprintf(os.Stderr, "unknown heartbeat command %q\n", args[0])
94			heartbeatUsage()
95			os.Exit(2)
96		}
97	}
98	
99	func heartbeatUsage() {
100		fmt.Println("usage: edgefleet heartbeat <submit|health|history> [flags]")
101		fmt.Println()
102		fmt.Println("commands:")
103		fmt.Println("  submit   receive heartbeats from stdin as a JSON array")
104		fmt.Println("  health   query node health from its latest telemetry")
105		fmt.Println("  history  list all heartbeats for a node, ascending by seq")
106		fmt.Println()
107		fmt.Println("input format (submit):")
108		fmt.Println("  A JSON array of heartbeat objects; every field is required.")
109		fmt.Println("    node          string   node id (non-empty)")
110		fmt.Println("    seq           integer  sequence number (> 0)")
111		fmt.Println("    collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00")
112		fmt.Println("                           must not be later than the receive time")
113		fmt.Println("    version       string   version (non-empty)")
114		fmt.Println("    height        integer  block height (>= 0)")
115		fmt.Println("    missed        integer  cumulative missed duties (>= 0)")
116		fmt.Println()
117		fmt.Println("  example:")
118		fmt.Println(`    [{"node":"val-eu-1","seq":7,"collected_at":"2026-10-01T11:59:00+08:00",`)
119		fmt.Println(`      "version":"1.26.0","height":12345,"missed":0}]`)
120		fmt.Println()
121		fmt.Println("flags:")
122		fmt.Println("  submit   --data-dir DIR        data directory (default: $EDGEFLEET_DATA_DIR or ~/.edgefleet)")
123		fmt.Println("           --receive-time TIME   receive time, RFC3339 (default: now)")
124		fmt.Println("  health   --node ID             node id (required)")
125		fmt.Println("           --expected-version V  expected version (required)")
126		fmt.Println("           --tolerated-misses N  tolerated missed duties, >= 0 (required)")
127		fmt.Println("           --missed-since-seq S  seq of a saved heartbeat used as the")
128		fmt.Println("                                missed-duty baseline (optional, > 0)")
129		fmt.Println("           --at TIME             query time, RFC3339 (default: now)")
130		fmt.Println("           --data-dir DIR        data directory")
131		fmt.Println()
132		fmt.Println("  Without --missed-since-seq the missed-duty alarm uses the cumulative")
