3	import (
4		"strings"
5		"testing"
6		"time"
7	)
8	
9	// These tests protect node identity at the two submit trust boundaries: the
10	// JSON command-line input and direct Store.Submit calls. A node id must be
11	// losslessly representable Unicode text. encoding/json silently rewrites
12	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
13	// would merge distinct node ids into one and later break the ownership
14	// check between a node's file and its records — so such input is rejected
15	// outright, never stored as a replacement-char id. A literal "�" typed by
16	// the user is a legal character and stays accepted.
17	
18	// recordJSON builds one heartbeat object around the given raw node token.
19	func recordJSON(nodeToken string) string {
20		return `[{"node":` + nodeToken + `,"seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`
21	}
22	
23	func TestParseHeartbeatsInvalidUTF8NodeRejected(t *testing.T) {
24		// 0xFF is not valid UTF-8 anywhere; a lenient decode would turn it into
25		// U+FFFD and silently rename the node.
26		input := []byte(recordJSON(`"val-` + "\xff" + `1"`))
27		_, err := ParseHeartbeats(input, testBase)
28		if err == nil {
29			t.Fatalf("invalid UTF-8 in node must be rejected")
30		}
31		if !strings.Contains(err.Error(), "record 1") || !strings.Contains(err.Error(), "node") {
32			t.Errorf("error must name the record position and the node field, got: %v", err)
33		}
34	
35		// The same failure at a later batch position reports that position.
36		two := `[
37			{"node":"good","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0},
38			{"node":"bad-` + "\xff" + `","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}
39		]`
40		_, err = ParseHeartbeats([]byte(two), testBase)
41		if err == nil || !strings.Contains(err.Error(), "record 2") || !strings.Contains(err.Error(), "node") {
42			t.Errorf("error must name record 2 and the node field, got: %v", err)
43		}
44	}
45	
46	func TestParseHeartbeatsUnpairedSurrogateRejected(t *testing.T) {
47		cases := []struct {
48			name      string
49			nodeToken string
50		}{
51			{"lone high surrogate", `"val\uD83D"`},
52			{"lone low surrogate", `"val\uDE00"`},
53			{"high surrogate at end", `"\uD83D"`},
54			{"high surrogate then plain char", `"\uD83Dx"`},
55			{"high surrogate then non-surrogate escape", `"\uD83DA"`},
56			{"high surrogate then another high", `"\uD83D\uD83D"`},
57			{"high surrogate then escaped quote", `"\uD83D\""`},
58		}
59		for _, tc := range cases {
60			t.Run(tc.name, func(t *testing.T) {
61				_, err := ParseHeartbeats([]byte(recordJSON(tc.nodeToken)), testBase)
62				if err == nil {
63					t.Fatalf("unpaired surrogate in node must be rejected")
64				}
65				if !strings.Contains(err.Error(), "record 1") || !strings.Contains(err.Error(), "node") {
66					t.Errorf("error must name the record position and the node field, got: %v", err)
67				}
68			})
69		}
70	}
71	
