1	package edgefleet
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"os"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// These tests protect the read-side trust boundary. Submit input is parsed
15	// strictly, but the saved file itself must be held to the same rules: every
16	// telemetry field explicitly present, non-null and written once. An attacker
17	// who can edit the file must not be able to delete a field whose saved value
18	// happened to be zero (missed=0, height=0), write null, or repeat a field,
19	// and then have health queries treat the zero-filled interpretation as real
20	// telemetry — not even when the stored checksum matches that interpretation.
21	
22	// tamperedFile writes a node file whose checksum matches the records *as a
23	// lenient struct unmarshal would interpret them*: a missing field decodes to
24	// zero and duplicate keys keep the last value, exactly the values over which
25	// a naive reader would (re)compute a matching checksum. This simulates the
26	// strongest version of the attack.
27	func tamperedFile(t *testing.T, path, recordsJSON string) {
28		t.Helper()
29		var interpreted []Heartbeat
30		if err := json.Unmarshal([]byte(recordsJSON), &interpreted); err != nil {
31			t.Fatalf("test setup: lenient decode failed: %v", err)
32		}
33		content := fmt.Sprintf(`{"format":%q,"checksum":%q,"records":%s}`,
34			formatMarker, checksumRecords(interpreted), recordsJSON)
35		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
36			t.Fatal(err)
37		}
38	}
39	
40	// sha256Hex mirrors checksumRecords for raw JSON the test builds by hand.
41	func sha256Hex(t *testing.T, data []byte) string {
42		t.Helper()
43		sum := sha256.Sum256(data)
44		return hex.EncodeToString(sum[:])
45	}
46	
47	const validRecordJSON = `{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":100,"missed":0}`
48	
49	func TestStoredMissingFieldWithMatchingChecksumIsCorrupt(t *testing.T) {
50		dir := t.TempDir()
51		store, err := OpenStore(dir)
52		if err != nil {
53			t.Fatal(err)
54		}
55		path := store.nodePath("n1")
56	
57		cases := []struct {
58			name        string
59			recordsJSON string
60			field       string
61		}{
62			{"missing node", `[{"seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":100,"missed":0}]`, "node"},
63			{"missing seq", `[{"node":"n1","collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":100,"missed":0}]`, "seq"},
64			{"missing collected_at", `[{"node":"n1","seq":1,"version":"1.0","height":100,"missed":0}]`, "collected_at"},
65			{"missing version", `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","height":100,"missed":0}]`, "version"},
66			// The exact regression: the record really had height 0; deleting the
67			// field and reusing a checksum computed over the zero-filled record
68			// must not make height 0 look like reported telemetry.
69			{"missing height that was zero", `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","missed":0}]`, "height"},
70			{"missing missed that was zero", `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":100}]`, "missed"},
71		}
72		for _, tc := range cases {
73			t.Run(tc.name, func(t *testing.T) {
74				tamperedFile(t, path, tc.recordsJSON)
75	
76				_, err := loadNodeFile(path)
