380	// corruptNodeFile overwrites one node's saved file with raw content.
381	func corruptNodeFile(t *testing.T, dir, node, content string) {
382		t.Helper()
383		if err := os.WriteFile(nodeFileHexPath(dir, node), []byte(content), 0o644); err != nil {
384			t.Fatal(err)
385		}
386	}
