503	// TestCLISubmitRejectsBatchTouchingCorruptNode ensures a batch is refused
504	// before any new record is saved: the corrupt file stays byte-for-byte
505	// intact, other files in the batch are not written, and no new node file is
506	// created. Submitting only to healthy nodes continues to work.
507	func TestCLISubmitRejectsBatchTouchingCorruptNode(t *testing.T) {
508		f := newFixture(t)
509	
510		const canonical = `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100,"missed":0}]`
511		submitBatch(t, f.dir, "["+strings.Trim(canonical, "[]")+"]")
512		// Delete "missed" from the genuine record (its value was 0); keep the
513		// original checksum, which still matches the zero-filled interpretation.
514		corruptNodeFile(t, f.dir, "bad", envelope(strictChecksum(canonical),
515			`[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":100}]`))
516	
517		badBefore := readNodeFile(t, f.dir, "bad")
518		monoBefore := readNodeFile(t, f.dir, "mono")
519	
520		batch := `[
521		  {"node":"bad","seq":2,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":102,"missed":0},
522		  {"node":"mono","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":104,"missed":15},
523		  {"node":"brandnew","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}
524		]`
525		out, errOut, code := runCLI(t, f.dir, batch,
526			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
527		if code == 0 {
528			t.Errorf("submit touching a corrupt node must fail non-zero; stdout=%q stderr=%q", out, errOut)
529		}
530		if strings.Contains(out, "submitted") {
531			t.Errorf("rejected batch must not report success, stdout=%q", out)
532		}
533		if !strings.Contains(errOut, "corruption") || !strings.Contains(errOut, "missed") {
534			t.Errorf("submit stderr must explain the corruption, got %q", errOut)
535		}
536	
537		if got := readNodeFile(t, f.dir, "bad"); got != badBefore {
538			t.Errorf("corrupt node file was modified during rejected submit")
539		}
540		if got := readNodeFile(t, f.dir, "mono"); got != monoBefore {
541			t.Errorf("healthy node file was rewritten during rejected submit")
542		}
543		if _, err := os.Stat(nodeFileHexPath(f.dir, "brandnew")); !os.IsNotExist(err) {
544			t.Errorf("brand-new node file must not be created, stat err=%v", err)
545		}
546	
547		// Healthy nodes are unaffected and remain fully usable.
548		out, _, code = health(t, f,
549			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
550		if code != 0 || !strings.Contains(out, "node=mono") {
551			t.Errorf("healthy node must still query normally: code=%d out=%q", code, out)
552		}
553		submitBatch(t, f.dir, `[{"node":"gappy","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":304,"missed":4}]`)
554	}
