556	// TestCLIMisownedNodeFileIsRefused plants one node's complete, checksum-valid
557	// file under another node's name and checks the command line refuses to serve
558	// it as the wrong node's telemetry: health (plain and with a baseline),
559	// history and submit all fail non-zero with the reason on stderr, while the
560	// real owner keeps working.
561	func TestCLIMisownedNodeFileIsRefused(t *testing.T) {
562		f := newFixture(t)
563	
564		// Copy mono's intact file over gappy's. Format and checksum stay valid;
565		// only the ownership is wrong.
566		corruptNodeFile(t, f.dir, "gappy", readNodeFile(t, f.dir, "mono"))
567		misownedPath := nodeFileHexPath(f.dir, "gappy")
568	
569		for _, tc := range []struct {
570			name string
571			args []string
572		}{
573			{"health", []string{"--node", "gappy", "--expected-version", "1.26.0", "--tolerated-misses", "9"}},
574			{"health with baseline", []string{"--node", "gappy", "--expected-version", "1.26.0", "--tolerated-misses", "9", "--missed-since-seq", "1"}},
575		} {
576			t.Run(tc.name, func(t *testing.T) {
577				out, errOut, code := health(t, f, tc.args...)
578				if code == 0 {
579					t.Fatalf("misowned file must fail the query, exit=0 stdout=%q", out)
580				}
581				if out != "" {
582					t.Errorf("no health result may be printed, stdout=%q", out)
583				}
584				for _, want := range []string{misownedPath, "record 1", `"gappy"`, `"mono"`} {
585					if !strings.Contains(errOut, want) {
586						t.Errorf("stderr must contain %s, got %q", want, errOut)
587					}
588				}
589			})
590		}
591	
592		out, errOut, code := runCLI(t, f.dir, "",
593			"heartbeat", "history", "--data-dir", f.dir, "--node", "gappy")
594		if code == 0 {
595			t.Fatalf("history of a misowned file must fail, exit=0 stdout=%q", out)
596		}
597		if out != "" {
598			t.Errorf("no history may be printed, stdout=%q", out)
599		}
600		if !strings.Contains(errOut, misownedPath) || !strings.Contains(errOut, `"mono"`) {
601			t.Errorf("history stderr must name the file and the foreign node, got %q", errOut)
602		}
603	
604		// A submit batch touching the misowned node is refused as a whole: no
605		// success line, no counts, and the first-time node in the batch is not
606		// created either.
607		batch := `[
608		  {"node":"gappy","seq":9,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":999,"missed":0},
609		  {"node":"brandnew","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}
610		]`
611		out, errOut, code = runCLI(t, f.dir, batch,
612			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
613		if code == 0 {
614			t.Errorf("submit touching a misowned node must fail non-zero; stdout=%q", out)
615		}
616		if strings.Contains(out, "submitted") {
617			t.Errorf("rejected batch must not print success or counts, stdout=%q", out)
618		}
619		if !strings.Contains(errOut, misownedPath) {
620			t.Errorf("submit stderr must name the misowned file, got %q", errOut)
621		}
622		if _, err := os.Stat(nodeFileHexPath(f.dir, "brandnew")); !os.IsNotExist(err) {
623			t.Errorf("brand-new node file must not be created, stat err=%v", err)
624		}
625	
626		// The real owner of the copied records is unaffected.
627		out, _, code = health(t, f,
628			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
629		if code != 0 || !strings.Contains(out, "node=mono") {
630			t.Errorf("real owner must still query normally: code=%d out=%q", code, out)
631		}
