729		// Both nodes are queryable by their original ids.
730		out, _, code = runCLI(t, dir, "",
731			"heartbeat", "history", "--data-dir", dir, "--node", "val-�")
732		if code != 0 || !strings.Contains(out, "node=val-� seq=1") {
733			t.Errorf("history for literal replacement char id: code=%d out=%q", code, out)
