				t.Errorf("health must refuse corrupt data, got %v", err)
			}
			if _, err := store.HealthSince("bad", receive, "1.26.0", 0, 1); err == nil || !IsCorrupt(err) {
				t.Errorf("health with baseline must refuse corrupt data, got %v", err)
			}

