		name        string
		versionJSON string // raw version token in the tampered file
	}{
		{"invalid UTF-8 byte", `"1.26.0-` + "\xff" + `"`},
		{"unpaired high surrogate escape", `"1.26.0-😀"`},
		{"unpaired low surrogate escape", `"1.26.0-\uDE00"`},
	}
