		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			store, err := OpenStore(dir)
			if err != nil {
				t.Fatal(err)
			}

			// Another node holds genuine data and keeps working throughout.
			receive := testBase
			if _, _, err := store.Submit([]Heartbeat{
